    public static class Builder extends ContainerMappingMethodBuilder<Builder, IterableMappingMethod> {

        private Type mappedResultElementType;

        public Builder() {
            super( Builder.class, "collection element" );
        }

        @Override
        protected Type getElementType(Type parameterType) {
            if ( parameterType.isMapType() ) {
                return ctx.getTypeFactory().getMapEntryType( parameterType );
            }
            return parameterType.isArrayType() ? parameterType.getComponentType() : first(
                parameterType.determineTypeArguments( Iterable.class ) ).getTypeBound();
        }

        @Override
        protected Assignment getWrapper(Assignment assignment, Method method) {
            Type resultType = method.getResultType();
            // target accessor is setter, so decorate assignment as setter
            if ( resultType.isArrayType() || resultType.isMapType() ) {
                Type localVariableType = resultType.isMapType() ? getAssignmentResultType( assignment ) : resultType;
                mappedResultElementType = localVariableType;
                return new LocalVarWrapper( assignment, method.getThrownTypes(), localVariableType, false );
            }
            else {
                return new SetterWrapper( assignment, method.getThrownTypes(), false );
            }
        }

        private Type getAssignmentResultType(Assignment assignment) {
            if ( assignment instanceof MethodReference ) {
                Type returnType = ( (MethodReference) assignment ).getReturnType();
                if ( returnType != null ) {
                    return returnType;
                }
            }
            else if ( assignment instanceof TypeConversion ) {
                return getAssignmentResultType( ( (TypeConversion) assignment ).getAssignment() );
            }
            return getElementType( method.getResultType() );
        }

        @Override
        protected IterableMappingMethod instantiateMappingMethod(Method method, Collection<String> existingVariables,
